import{_ as o,a0 as p,w as s,s as a,ao as u,I as n,x as e,a1 as r,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const M=JSON.parse('{"title":"MultiWriter：同時將 ISO 鏡像併發寫入 20 個  USB 啓動盤 | LCTT x X-CMD","titleTemplate":false,"description":"MultiWriter：同時將 ISO 鏡像併發寫入 20 個  USB 啓動盤 | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"MultiWriter：同時將 ISO 鏡像併發寫入 20 個  USB 啓動盤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"MultiWriter：同時將 ISO 鏡像併發寫入 20 個  USB 啓動盤 | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20150106 This App Can Write a Single ISO to 20 USB Drives Simultaneously","title":"MultiWriter：同時將 ISO 鏡像併發寫入 20 個  USB 啓動盤","tag":"201503","desc":""},"relativePath":"201503/20150106 This App Can Write a Single ISO to 20 USB Drives Simultaneously.md","filePath":"[post].md"}'),m={name:"201503/20150106 This App Can Write a Single ISO to 20 USB Drives Simultaneously.md"};function S(g,t,d,T,b,f){const i=p("Link");return s(),a("div",null,[t[17]||(t[17]=u('<h1 id="multiwriter-同時將-iso-鏡像併發寫入-20-個-usb-啓動盤" tabindex="-1">MultiWriter：同時將 ISO 鏡像併發寫入 20 個 USB 啓動盤 <a class="header-anchor" href="#multiwriter-同時將-iso-鏡像併發寫入-20-個-usb-啓動盤" aria-label="Permalink to “MultiWriter：同時將 ISO 鏡像併發寫入 20 個  USB 啓動盤”">​</a></h1><p><strong>我的問題是如何把一個Linux ISO 文件燒錄到 17 個 USB 啓動盤？</strong></p><p>精通代碼的人會寫一個 bash 腳本來自動化處理，而大部分的人會使用像 USB 啓動盤創建器這樣的圖形用户界面工具來把 ISO 文件一個、一個的燒錄到驅動盤中。但剩下的還有一些人也許會很快得出結論，兩種方法都不太理想。</p><h3 id="問題-解決" tabindex="-1">問題 &gt; 解決 <a class="header-anchor" href="#問題-解決" aria-label="Permalink to “問題 &gt; 解決”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2015/01/gnome-multi-writer.jpg" alt="GNOME MultiWriter in action"></p><p><em>GNOME MultiWriter 在運行當中</em></p><p>Richard Hughes，一個 GNOME 開發者，也面臨着類似的困境。他要創建一批預裝操作系統的 USB 啓動盤，需要一個足夠簡單的工具，使得像他父親這樣的用户也能使用。</p><p>他的反應是開發<strong>品牌性的新應用程序</strong>，使上面的兩種方法合二為一，創造出易用的一款工具。</p>',8)),n("p",null,[t[1]||(t[1]=e("它的名字就叫 “",-1)),r(i,{href:"https://github.com/hughsie/gnome-multi-writer/"},{default:l(()=>[...t[0]||(t[0]=[e("GNOME MultiWriter",-1)])]),_:1}),t[2]||(t[2]=e("”，可以同時把單個的 ISO 或 IMG 文件寫入多個 USB 驅動盤。",-1))]),t[18]||(t[18]=u(`<p>它不支持個性化自定義或命令列執行的功能，使用它就可以省掉浪費一下午的時間來對相同的操作的重複動作。</p><p>您需要的就是這一款應用程序、一個 ISO 鏡像文件、一些拇指驅動盤以用許多空 USB 接口。</p><h3 id="用例和安裝" tabindex="-1">用例和安裝 <a class="header-anchor" href="#用例和安裝" aria-label="Permalink to “用例和安裝”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2015/01/mutli-writer-on-ubuntu.jpg" alt="The app can be installed on Ubuntu"></p><p><em>該應用程序可以在 Ubuntu 上安裝</em></p><p>這款應用程序的定義使用場景很不錯，正適合使用於預裝正要發佈的操作系統或 live 映像的 USB 啓動盤上。</p><p>那就是説，任何人想要創建一個單獨可啓動的 USB 啓動盤的話，也是一樣的適用 - 因我用 Ubuntu 的內置磁盤創建工具來創建可引導的映像從來沒有一次成功過的，所以這方案對我來説是個好消息！</p><p>它的開發者 Hughes 説它<strong>最高能支持20個 USB 啓動盤</strong>，每個盤的大小在 1GB 到 32GB之間。</p><p>GNOME MultiWriter 也有不好的地方（到現在為止）就是它還沒有一個完結、穩定的成品。它是能工作，但在早期的時候，還沒有可安裝的二進制版本或可添加到你龐大軟件源的 PPA。</p><p>如果您知道通常的 configure/make 的操作流程的話，可以獲取其源碼並隨時都可以編譯運行。在 Ubuntu14.10 系統上，你可能還需要首先安裝以下軟件包：</p><pre><code>sudo apt-get install gnome-common yelp-tools libcanberra-gtk3-dev libudisks2-dev gobject-introspection
</code></pre><p>如果您可以運行起來，已經玩轉的話，給我們分享下您的感受！</p><p>此項目託管在 GitHub 上，盼望對其提出問題缺陷和發起 pull 請求，在上面也可以找到壓縮包下載，進行手動安裝。</p>`,13)),n("ul",null,[n("li",null,[r(i,{href:"https://github.com/hughsie/gnome-multi-writer/"},{default:l(()=>[...t[3]||(t[3]=[e("Github 上的 GNOME MultiWriter",-1)])]),_:1})])]),t[19]||(t[19]=n("hr",null,null,-1)),n("p",null,[t[5]||(t[5]=e("via: ",-1)),r(i,{href:"http://www.omgubuntu.co.uk/2015/01/gnome-multiwriter-iso-usb-utility"},{default:l(()=>[...t[4]||(t[4]=[e("http://www.omgubuntu.co.uk/2015/01/gnome-multiwriter-iso-usb-utility",-1)])]),_:1})]),n("p",null,[t[9]||(t[9]=e("作者：",-1)),r(i,{href:"https://plus.google.com/117485690627814051450/?rel=author"},{default:l(()=>[...t[6]||(t[6]=[e("Joey-Elijah Sneddon",-1)])]),_:1}),t[10]||(t[10]=e(" 譯者：",-1)),r(i,{href:"https://github.com/runningwater"},{default:l(()=>[...t[7]||(t[7]=[e("runningwater",-1)])]),_:1}),t[11]||(t[11]=e(" 校對：",-1)),r(i,{href:"https://github.com/wxy"},{default:l(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[14]||(t[14]=e("本文由 ",-1)),r(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[12]||(t[12]=[e("LCTT",-1)])]),_:1}),t[15]||(t[15]=e(" 原創翻譯，",-1)),r(i,{href:"http://linux.cn/"},{default:l(()=>[...t[13]||(t[13]=[e("Linux中國",-1)])]),_:1}),t[16]||(t[16]=e(" 榮譽推出",-1))])])}const U=o(m,[["render",S]]);export{M as __pageData,U as default};
